public final class PolicyInterceptor implements ServerInterceptor {
  @Override public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
      ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
    var started = System.nanoTime();                        // policy
    var listener = next.startCall(new RecordingCall<>(call, started), headers);
    return listener;                                        // delegate to service
  }
}
